import{_ as a,o as i,c as e,ag as d}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"SetMatrixFourPoint 四点设置矩阵","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/16. 阵列指令/SetMatrixFourPoint.md","filePath":"3. 指令/16. 阵列指令/SetMatrixFourPoint.md","lastUpdated":1778862643000}'),r={name:"3. 指令/16. 阵列指令/SetMatrixFourPoint.md"};function s(n,t,o,h,l,p){return i(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="setmatrixfourpoint-四点设置矩阵" tabindex="-1">SetMatrixFourPoint 四点设置矩阵 <a class="header-anchor" href="#setmatrixfourpoint-四点设置矩阵" aria-label="Permalink to &quot;SetMatrixFourPoint 四点设置矩阵&quot;">​</a></h1><p>该指令以指定四个点形成空间中的一个四边形，并将这个四边形按照设置的行数和列数进行等分得到一个矩阵点组。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetMatrixFourPoint(P1, P2, P3, P4, Row, Column) SetMatrixFourPoint(原点, 行方向最后点, 列方向最后点, 原点对角点, 行数, 列数)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>P1</td><td>CPOS 变量</td><td>指定平行四边形的第一个点，也称为原点。</td><td></td></tr><tr><td>P2</td><td>CPOS 变量</td><td>指定平行四边形的行方向上的最后一个点。</td><td></td></tr><tr><td>P3</td><td>CPOS 变量</td><td>指定平行四边形的列方向上的最后一个点。</td><td></td></tr><tr><td>P4</td><td>CPOS 变量</td><td>指定平行四边形的原点对角点。</td><td></td></tr><tr><td>Row</td><td>int</td><td>生成矩阵的行数。</td><td></td></tr><tr><td>Column</td><td>int</td><td>生成矩阵的列数。</td><td></td></tr></tbody></table><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p>将 P1、P2、P3、P4 形成的四边形按照 4 行 5 列均分：</p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetMatrixFourPoint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, P2, P3, P4, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑解析</strong>： 以 P1、P2、P3、P4 四个点构成四边形，并按 4 行 5 列等分生成矩阵点组。</p>',11)])])}const c=a(r,[["render",s]]);export{u as __pageData,c as default};
